#!/bin/bash
# Build protoc 2.3.0 as a native host tool from the Source SDK 2013 copy in
# sdk2013mp/thirdparty/protobuf-2.3.0. The retail hl2mp client links Valve's
# htmlmessages.pb.o, generated by this protoc version (the SDK's own
# devtools/bin/osx32/protoc is i386-only and can't run on Apple Silicon).
#
# Usage: build-protoc.sh [--prefix DIR] [--work DIR]
#
# Installs <prefix>/protoc-2.3.0/bin/protoc. Generated code depends on the
# protoc version only, not on the host compiler.
set -euo pipefail
HERE=$(cd "$(dirname "$0")" && pwd)
. "$HERE/versions.sh"

PREFIX=$BYTEMATCH_TOOLCHAIN WORK=
while [ $# -gt 0 ]; do
	case $1 in
	--prefix) PREFIX=$2; shift 2 ;;
	--work) WORK=$2; shift 2 ;;
	-h|--help) sed -n '2,10p' "$0"; exit 0 ;;
	*) echo "unknown option $1" >&2; exit 2 ;;
	esac
done
SRC=$(cd "$HERE/../../../sdk2013mp/thirdparty/protobuf-2.3.0/src" && pwd)
WORK=${WORK:-$PREFIX/work}/protoc-2.3.0
DEST=$PREFIX/protoc-2.3.0
rm -rf "$WORK"
mkdir -p "$WORK/obj" "$DEST/bin"

# config.h: pthreads, no hash_map (stubs/hash.h then uses std::map). message.cc
# relies on <istream> arriving transitively, which current libc++ no longer does.
cat > "$WORK/config.h" <<'EOF'
#define HAVE_PTHREAD 1
EOF

sources=$(python3 - "$SRC/Makefile.am" <<'EOF'
import re, sys
t = open(sys.argv[1]).read().replace('\\\n', ' ')
for var in ('libprotobuf_lite_la_SOURCES', 'libprotobuf_la_SOURCES', 'libprotoc_la_SOURCES', 'protoc_SOURCES'):
	for f in re.search(r'^' + var + r'\s*=(.*)$', t, re.M).group(1).split():
		if f.endswith('.cc'):
			print(f)
EOF
)

CXX=$(xcrun -f clang++)
SYSROOT=$(xcrun --show-sdk-path)
export WORK SRC CXX SYSROOT
printf '%s\n' $sources | xargs -P "$BYTEMATCH_JOBS" -n 1 sh -c \
	'"$CXX" -isysroot "$SYSROOT" -std=gnu++98 -O1 -w -include iostream -DHAVE_CONFIG_H -I"$WORK" -I"$SRC" \
		-c "$SRC/$1" -o "$WORK/obj/$(echo "$1" | tr / _).o"' _
"$CXX" -isysroot "$SYSROOT" -o "$DEST/bin/protoc" "$WORK"/obj/*.o -lpthread -lz
"$DEST/bin/protoc" --version || true  # 2.3.0 exits 1 after printing it
echo "installed $DEST/bin/protoc"
